class Order {
    private OrderLine ol;   // never created/received: field
    private Customer c;     // never created/received: field
    public double calculatePrice() {         // found message into :Order
        int qty = ol.getQuantity();          // OrderLine has getQuantity()
        Product p = ol.getProduct();         // reply p: local variable
        double price = p.getPricingDetails();// Product has the method
        double bPrice = calculateBasicPrice(qty, price); // self
        double discount = calculateDiscounts();          // self
        return calculateTotalPrice(bPrice, discount);    // reply total
    }
    private double calculateBasicPrice(int q, double pr) { return q * pr; }
    private double calculateDiscounts() { return c.getDiscountInfo(); }
    private double calculateTotalPrice(double b, double d) { return b - d; }
}

class Checkout {
    public Receipt pay(Item it, Card card) {
        double amt = it.getPrice();
        boolean ok = card.charge(amt);
        Receipt r = null;
        if (ok) {
            r = new Receipt(amt);
            r.print();
        }
        return r;
    }
}
